74	2026-06-03 13:09:54.214831+00	2026-06-03 13:09:54.214831+00	Crecimiento × Rating	Un país puede crecer mucho pero tener rating bajo (mala experiencia = se queman rápido). Cruzar crecimiento con rating promedio.  Los países en el cuadrante **superior derecho** (alto crecimiento + alto rating) son los mercados estrella para invertir. Si Portugal creció 80% y mantiene rating alto, ahí hay una oportunidad mejor que pelear en un mercado saturado."*	scatter	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"WITH anual AS (\\n  SELECT h.city_country,\\n         EXTRACT(YEAR FROM r.review_date) AS anio,\\n         COUNT(*) AS reviews,\\n         AVG(r.rating_overall) AS rating\\n  FROM stg_reviews r\\n  JOIN stg_hostels h ON r.id_hostel = h.id_hostel\\n  WHERE EXTRACT(YEAR FROM r.review_date) IN (2022, 2023)\\n  GROUP BY h.city_country, anio\\n)\\nSELECT a.city_country AS \\"País\\",\\n       a.reviews AS \\"2022\\",\\n       b.reviews AS \\"2023\\",\\n       ROUND((b.reviews - a.reviews) * 100.0 / NULLIF(a.reviews, 0), 1) AS \\"Crecimiento %\\",\\n       ROUND(b.rating, 1) AS \\"Rating 2023\\"\\nFROM anual a\\nJOIN anual b ON a.city_country = b.city_country\\nWHERE a.anio = 2022 AND b.anio = 2023 AND a.reviews >= 100\\nORDER BY \\"Crecimiento %\\" DESC\\nLIMIT 15;"}]}	{"graph.dimensions":["Crecimiento %"],"graph.metrics":["Rating 2023"],"graph.series_order_dimension":null,"graph.series_order":null,"graph.x_axis.scale":"linear"}	1	2	\N	native	f	\N	\N	\N	f	\N	\N	[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"País","lib/original-name":"País","name":"País","lib/source":"source/native","lib/source-column-alias":"País","source":"native","field_ref":["field","País",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"País","display_name":"País","fingerprint":{"global":{"distinct-count":15,"nil%":0.0},"type":{"type/Text":{"max-length":20.0,"min-length":4.0,"percent-email":0.0,"percent-s