71	2026-06-03 12:37:54.703277+00	2026-06-03 12:37:54.703277+00	Cobertura por país (asc — los peores primero)	Muestra donde priorizar reseñas	table	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT h.city_country AS \\"País\\",\\n       COUNT(DISTINCT h.id_hostel) AS \\"Total Hostels\\",\\n       COUNT(DISTINCT r.id_hostel) AS \\"Con Reseñas\\",\\n       ROUND(COUNT(DISTINCT r.id_hostel) * 100.0 /\\n             NULLIF(COUNT(DISTINCT h.id_hostel), 0), 1) AS \\"Cobertura %\\"\\nFROM stg_hostels h\\nLEFT JOIN stg_reviews r ON h.id_hostel = r.id_hostel\\nGROUP BY h.city_country\\nHAVING COUNT(DISTINCT h.id_hostel) >= 50\\nORDER BY \\"Cobertura %\\" ASC\\nLIMIT 20;"}]}	{"column_settings":{"[\\"name\\",\\"Cobertura %\\"]":{"show_mini_bar":true,"number_style":"percent","scale":0.01}},"table.pivot_column":"Cobertura %","table.cell_column":"Total Hostels"}	1	2	\N	native	f	\N	\N	\N	f	\N	\N	[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"País","lib/original-name":"País","name":"País","lib/source":"source/native","lib/source-column-alias":"País","source":"native","field_ref":["field","País",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"País","display_name":"País","fingerprint":{"global":{"distinct-count":20,"nil%":0},"type":{"type/Text":{"max-length":22,"min-length":4,"percent-email":0,"percent-state":0.05,"average-length":7.8,"percent-json":0,"percent-url":0,"mode-fraction":0.05,"top-3-fraction":0.15,"percent-blank":0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":null,"lib/deduplicated-name":"Total Hostels","lib/original-name":"Total Hostels","name":"Total Hostels","lib/source":"source/native","lib/source-column-alias":"Total Hostels","source":"native","field_ref":["field","Total Hostels",{"base-type":"type/BigInteger"}],"effective_type":"type/BigInteger","lib/desired-column-alias":"Total Hostels","display_name":"Total Hostels","fingerprint":{"globa