66	2026-06-02 20:45:47.504111+00	2026-06-02 20:50:49.009198+00	Tabla Top 20 países destino por volumen y rating	\N	table	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    h.city_country                              AS \\"País de Destino\\",\\n    COUNT(DISTINCT h.id_hostel)                 AS \\"Hostels Registrados\\",\\n    COUNT(DISTINCT CASE\\n        WHEN kr.id_hostel IS NOT NULL\\n        THEN h.id_hostel END)                   AS \\"Hostels con Reseñas\\",\\n    COUNT(r.id_review)                          AS \\"Total Reseñas\\",\\n    ROUND(AVG(r.rating_overall), 1)             AS \\"Rating Promedio\\",\\n    ROUND(COUNT(r.id_review) * 1.0\\n          / NULLIF(COUNT(DISTINCT h.id_hostel),\\n          0), 0)                                AS \\"Reseñas por Hostel\\",\\n    CASE\\n        WHEN AVG(r.rating_overall) >= 85\\n             AND COUNT(r.id_review) >= 10000\\n             THEN '🏆 Mercado Premium'\\n        WHEN AVG(r.rating_overall) >= 80\\n             AND COUNT(r.id_review) >= 5000\\n             THEN '⭐ Mercado Fuerte'\\n        WHEN COUNT(r.id_review) >= 5000\\n             THEN '📈 Alto Volumen'\\n        ELSE '📊 Mercado Emergente'\\n    END                                         AS \\"Clasificación\\"\\nFROM stg_hostels h\\nLEFT JOIN stg_reviews r ON h.id_hostel = r.id_hostel\\nLEFT JOIN kpi_hostel_ratings kr ON h.id_hostel = kr.id_hostel\\nWHERE r.rating_overall IS NOT NULL\\nGROUP BY h.city_country\\nHAVING COUNT(r.id_review) >= 500\\nORDER BY COUNT(r.id_review) DESC\\nLIMIT 20;"}]}	{"table.columns":[{"name":"País de Destino","enabled":true},{"name":"Hostels Registrados","enabled":true},{"name":"Hostels con Reseñas","enabled":false},{"name":"Total Reseñas","enabled":true},{"name":"Rating Promedio","enabled":true},{"name":"Reseñas por Hostel","enabled":false},{"name":"Clasificación","enabled":true}],"table.pivot_column":"Clasificación","table.cell_column":"Hostels Registrados","column_settings