60	2026-05-26 20:05:38.808483+00	2026-06-01 23:09:02.544567+00	Volumen de reseñas por perfil de viajero (OK) 	Qué segmento genera más actividad en la plataforma, qué combinación de tipo de viaje + género genera más reseñas. Útil para saber dónde concentrar presupuesto publicitario.	bar	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    u.trip_code                             AS \\"Tipo de Viaje\\",\\n    u.gender_code                           AS \\"Género\\",\\n    COUNT(r.id_review)                      AS \\"Total Reseñas\\",\\n    ROUND(AVG(r.rating_overall), 1)         AS \\"Rating Promedio\\",\\n    ROUND(COUNT(r.id_review) * 100.0\\n          / SUM(COUNT(r.id_review)) OVER (), 1) AS \\"% del Total de Reseñas\\"\\nFROM stg_reviews r\\nJOIN stg_users u ON r.id_user = u.id_user\\nWHERE u.trip_code IS NOT NULL\\n  AND u.gender_code IS NOT NULL\\n  AND r.rating_overall IS NOT NULL\\nGROUP BY u.trip_code, u.gender_code\\nORDER BY COUNT(r.id_review) DESC;"}]}	{"graph.x_axis.scale":"ordinal","graph.dimensions":["Tipo de Viaje","Género"],"graph.metrics":["Total Reseñas","Rating Promedio","% del Total de Reseñas"]}	1	2	\N	native	f	\N	\N	\N	f	\N	\N	[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Tipo de Viaje","lib/original-name":"Tipo de Viaje","name":"Tipo de Viaje","lib/source":"source/native","lib/source-column-alias":"Tipo de Viaje","source":"native","field_ref":["field","Tipo de Viaje",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Tipo de Viaje","display_name":"Tipo de Viaje","fingerprint":{"global":{"distinct-count":6,"nil%":0.0},"type":{"type/Text":{"max-length":15.0,"min-length":5.0,"percent-email":0.0,"percent-state":0.0,"average-length":9.5,"percent-json":0.0,"percent-url":0.0,"mode-fraction":0.16666666666666666,"top-3-fraction":0.5,"percent-blank":0.0}}},"base_type":"type/Text"},{"database_type":"varchar","semantic_type":null,"lib/deduplicated-