61	2026-05-26 20:10:22.084503+00	2026-06-01 23:10:35.103524+00	Tipo de alojamiento x rango etario	Qué tipo de hospedaje prefiere cada edad(para segmentar anuncios por producto)\nTipo de alojamiento por edad → qué producto prefiere cada rango etario. Para segmentar campañas por producto (hostel vs hotel vs guesthouse).	row	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    u.age_range                             AS \\"Rango Etario\\",\\n    h.type                                  AS \\"Tipo de Alojamiento\\",\\n    COUNT(r.id_review)                      AS \\"Total Reseñas\\",\\n    ROUND(AVG(r.rating_overall), 1)         AS \\"Rating Promedio\\",\\n    ROUND(COUNT(r.id_review) * 100.0\\n          / SUM(COUNT(r.id_review)) OVER (PARTITION BY u.age_range), 1)\\n                                            AS \\"% dentro del Rango Etario\\"\\nFROM stg_reviews r\\nJOIN stg_users u ON r.id_user = u.id_user\\nJOIN stg_hostels h ON r.id_hostel = h.id_hostel\\nWHERE u.age_range IS NOT NULL\\n  AND r.rating_overall IS NOT NULL\\nGROUP BY u.age_range, h.type\\nHAVING COUNT(r.id_review) >= 100\\nORDER BY u.age_range, COUNT(r.id_review) DESC;"}]}	{"graph.dimensions":["Tipo de Alojamiento","Rango Etario"],"graph.metrics":["Total Reseñas","Rating Promedio","% dentro del Rango Etario"]}	1	2	\N	native	t	\N	\N	\N	f	\N	\N	[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Rango Etario","lib/original-name":"Rango Etario","name":"Rango Etario","lib/source":"source/native","lib/source-column-alias":"Rango Etario","source":"native","field_ref":["field","Rango Etario",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Rango Etario","display_name":"Rango Etario","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Text":{"max-length":5.0,"min-length":3.0,"percent-email":0.0,"percent-state":0.0,"average-length":4.5,"percent-json":0.0,"percent-url":0.0,"mode-fraction":