70	2026-06-03 12:21:54.089011+00	2026-06-03 12:21:54.089011+00	Satisfacción por rango etario y tipo de viaje - Scatter plot	🏆 Target Premium → son muchos usuarios Y están muy satisfechos. Son los mejores clientes para mostrarles publicidad porque ya les gusta la plataforma — es fácil convencerlos de volver.\n⭐ Alto Valor → están satisfechos pero son menos usuarios. Vale la pena apuntarles pero con menos presupuesto.\n👍 Valor Medio → ni tan satisfechos ni tantos. Se puede intentar pero no es prioridad.\n⚠️ Muestra insuficiente → hay tan poca gente en ese grupo que no podés sacar conclusiones. Ignoralos por ahora.\nLa idea principal del dashboard es: no gastes plata en publicidad para todos por igual. Concentrá el presupuesto en los 🏆 Target Premium porque ya están contentos y son más fáciles de retener. Los grupos con bajo rating o poca muestra no vale la pena atacar todavía.	scatter	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    u.age_range                                 AS \\"Rango Etario\\",\\n    u.trip_code                                 AS \\"Tipo de Viaje\\",\\n    COUNT(r.id_review)                          AS \\"Total Reseñas\\",\\n    ROUND(AVG(r.rating_overall), 1)             AS \\"Rating Promedio Overall\\",\\n    ROUND(AVG(r.rating_cleanliness), 1)         AS \\"Limpieza\\",\\n    ROUND(AVG(r.rating_atmosphere), 1)          AS \\"Atmósfera\\",\\n    ROUND(AVG(r.rating_staff), 1)               AS \\"Staff\\",\\n    CASE\\n        WHEN AVG(r.rating_overall) >= 85\\n             AND COUNT(r.id_review) >= 5000\\n             THEN '🏆 Target Premium'\\n        WHEN AVG(r.rating_overall) >= 80\\n             AND COUNT(r.id_review) >= 2000\\n             THEN '⭐ Alto Valor'\\n        WHEN AVG(r.rating_overall) >= 75\\n             AND COUNT(r.id_review) >= 1000\\n             THEN '👍 Valor Medio'\\n        WHEN COUNT(r.id_review) < 300\\n             THEN '⚠️ Muestra insuficiente'\\n        ELSE '📊 Volumen bajo o rating moderado'\\n    END                                         AS \\"Segmento\\"\\nFROM stg_reviews r\\nJOIN stg_users u ON r.id_user = u.id_user\\nWHERE u.age_range IS NOT NULL\\n  AND u.trip_code IS NOT NULL\\n  AND r.rating_overall IS NOT NULL\\nGROUP BY u.age_range, u.trip_code\\nHAVING COUNT(r.id_review) >= 100\\nORDER BY AVG(r.rating_overall) DESC, COUNT(r.id_review) DESC;"}]}	{"graph.y_axis.title_text":"Rating Promedio","scatter.bubble":"Total Reseñas","table.columns":[{"name":"Rango Etario","enabled":true},{"name":"Tipo de Viaje","enabled":true},{"name":"Total Reseñas","enabled":true},{"name":"Rating Promedio Overall","enabled":true},{"name":"Limpieza","enabled":false},{"name":"Atmósfera","enabled":false},{"name":"Staff","enabled":false},{"name":"Segmento","enabled":true}],"table.cell_column":"Total Reseñas","graph.series_order_dimension":null,"graph.x_axis.axis_enabled":true,"graph.metrics":["Rating Promedio Overall"],"graph.tooltip_columns":["[\\"name\\",\\"Rango Etario\\"]","[\\"name\\",\\"Tipo de Viaje\\"]","[\\"name\\",\\"Segmento\\"]"],"graph.y_axis.unpin_from_zero":true,"graph.series_order":null,"table.pivot_column":"Rango Etario","column_settings":{"[\\"name\\",\\"Rating Promedio Overall\\"]":{"show_mini_bar":true,"number_style":"decimal"}},"series_settings":{"Rating Promedio Overall":{"color":"#EF8C8C","axis":null}},"graph.y_axis.auto_range":true,"graph.x_axis.scale":"linear","graph.dimensions":["Total Reseñas"]}	1	2	\N	native	f	\N	\N	\N	f	\N	\N	[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Rango Etario","lib/original-name":"Rango Etario","name":"Rango Etario","lib/source":"source/native","lib/source-column-alias":"Rango Etario","source":"native","field_ref":["field","Rango Etario",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"Rango Etario","display_name":"Rango Etario","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Text":{"max-length":5.0,"min-len