69	2026-06-02 21:18:48.762621+00	2026-06-02 21:18:48.762621+00	Top segmentos de mayor valor combinado	\N	table	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    u.trip_code                                 AS \\"Tipo de Viaje\\",\\n    u.gender_code                               AS \\"Género\\",\\n    u.age_range                                 AS \\"Rango Etario\\",\\n    h.type                                      AS \\"Tipo Alojamiento\\",\\n    COUNT(r.id_review)                          AS \\"Total Reseñas\\",\\n    ROUND(AVG(r.rating_overall), 1)             AS \\"Rating Promedio\\",\\n    CASE\\n        WHEN AVG(r.rating_overall) >= 85\\n             AND COUNT(r.id_review) >= 5000\\n             THEN '🏆 Segmento Premium'\\n        WHEN AVG(r.rating_overall) >= 80\\n             AND COUNT(r.id_review) >= 2000\\n             THEN '⭐ Alto Valor'\\n        WHEN AVG(r.rating_overall) >= 75\\n             AND COUNT(r.id_review) >= 1000\\n             THEN '👍 Valor Medio'\\n        ELSE '📊 Volumen bajo o rating moderado'\\n    END                                         AS \\"Clasificación\\"\\nFROM stg_reviews r\\nJOIN stg_users u ON r.id_user = u.id_user\\nJOIN stg_hostels h ON r.id_hostel = h.id_hostel\\nWHERE u.trip_code IS NOT NULL\\n  AND u.gender_code IS NOT NULL\\n  AND u.age_range IS NOT NULL\\n  AND r.rating_overall IS NOT NULL\\n  AND h.type IN ('HOSTEL', 'GUESTHOUSE', 'HOTEL')\\n  AND u.gender_code IN ('FEMALE', 'MALE', 'COUPLE')\\nGROUP BY u.trip_code, u.gender_code, u.age_range, h.type\\nHAVING COUNT(r.id_review) >= 500\\nORDER BY AVG(r.rating_overall) DESC, COUNT(r.id_review) DESC\\nLIMIT 20;"}]}	{"table.pivot_column":"Tipo Alojamiento","table.cell_column":"Total Reseñas"}	1	2	\N	native	f	\N	\N	\N	f	\N	\N	[{"database_type":"varchar","semantic_type":null,"lib/deduplicated-name":"Tipo de Viaje","lib/original-name":"Tipo de Viaje","name":"Tipo de Viaje","lib/source":"source/native","lib/source-column-al