68	2026-06-02 21:15:36.886221+00	2026-06-02 21:15:36.886221+00	Satisfacción por rango etario y tipo de viaje	\N	table	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    u.age_range                                 AS \\"Rango Etario\\",\\n    u.trip_code                                 AS \\"Tipo de Viaje\\",\\n    COUNT(r.id_review)                          AS \\"Total Reseñas\\",\\n    ROUND(AVG(r.rating_overall), 1)             AS \\"Rating Promedio Overall\\",\\n    ROUND(AVG(r.rating_cleanliness), 1)         AS \\"Limpieza\\",\\n    ROUND(AVG(r.rating_atmosphere), 1)          AS \\"Atmósfera\\",\\n    ROUND(AVG(r.rating_staff), 1)               AS \\"Staff\\",\\n    CASE\\n        WHEN AVG(r.rating_overall) >= 85\\n             AND COUNT(r.id_review) >= 5000\\n             THEN '🏆 Target Premium'\\n        WHEN AVG(r.rating_overall) >= 80\\n             AND COUNT(r.id_review) >= 2000\\n             THEN '⭐ Alto Valor'\\n        WHEN AVG(r.rating_overall) >= 75\\n             AND COUNT(r.id_review) >= 1000\\n             THEN '👍 Valor Medio'\\n        WHEN COUNT(r.id_review) < 300\\n             THEN '⚠️ Muestra insuficiente'\\n        ELSE '📊 Volumen bajo o rating moderado'\\n    END                                         AS \\"Segmento\\"\\nFROM stg_reviews r\\nJOIN stg_users u ON r.id_user = u.id_user\\nWHERE u.age_range IS NOT NULL\\n  AND u.trip_code IS NOT NULL\\n  AND r.rating_overall IS NOT NULL\\nGROUP BY u.age_range, u.trip_code\\nHAVING COUNT(r.id_review) >= 100\\nORDER BY AVG(r.rating_overall) DESC, COUNT(r.id_review) DESC;"}]}	{"column_settings":{"[\\"name\\",\\"Rating Promedio Overall\\"]":{"show_mini_bar":true}},"table.columns":[{"name":"Rango Etario","enabled":true},{"name":"Tipo de Viaje","enabled":true},{"name":"Total Reseñas","enabled":true},{"name":"Rating Promedio Overall","enabled":true},{"name":"Limpieza","enabled":false},{"name":"Atmósfera","enabled":false},{"name":"Staff","enabled":fals