67	2026-06-02 20:53:48.184121+00	2026-06-02 20:53:48.184121+00	Top 20 nacionalidades de origen	\N	table	{"lib/type":"mbql/query","database":2,"stages":[{"lib/type":"mbql.stage/native","native":"SELECT\\n    u.nationality_name                          AS \\"Nacionalidad de Origen\\",\\n    COUNT(r.id_review)                          AS \\"Total Reseñas\\",\\n    COUNT(DISTINCT r.id_user)                   AS \\"Viajeros Únicos\\",\\n    ROUND(AVG(r.rating_overall), 1)             AS \\"Rating Promedio\\",\\n    ROUND(AVG(r.rating_cleanliness), 1)         AS \\"Limpieza\\",\\n    ROUND(AVG(r.rating_atmosphere), 1)          AS \\"Atmósfera\\",\\n    ROUND(AVG(r.rating_staff), 1)               AS \\"Staff\\",\\n    CASE\\n        WHEN AVG(r.rating_overall) >= 85\\n             AND COUNT(r.id_review) >= 5000\\n             THEN '🏆 Audiencia Premium'\\n        WHEN AVG(r.rating_overall) >= 80\\n             AND COUNT(r.id_review) >= 2000\\n             THEN '⭐ Audiencia Valiosa'\\n        ELSE '📊 Audiencia Estándar'\\n    END                                         AS \\"Valor para Pauta\\"\\nFROM stg_reviews r\\nJOIN stg_users u ON r.id_user = u.id_user\\nWHERE u.nationality_name IS NOT NULL\\n  AND r.rating_overall IS NOT NULL\\nGROUP BY u.nationality_name\\nHAVING COUNT(r.id_review) >= 200\\nORDER BY COUNT(r.id_review) DESC\\nLIMIT 20;"}]}	{"column_settings":{"[\\"name\\",\\"Total Reseñas\\"]":{"show_mini_bar":true},"[\\"name\\",\\"Rating Promedio\\"]":{"show_mini_bar":true}},"table.columns":[{"name":"Nacionalidad de Origen","enabled":true},{"name":"Total Reseñas","enabled":true},{"name":"Viajeros Únicos","enabled":false},{"name":"Rating Promedio","enabled":true},{"name":"Limpieza","enabled":false},{"name":"Atmósfera","enabled":false},{"name":"Staff","enabled":false},{"name":"Valor para Pauta","enabled":true}],"table.pivot_column":"Valor para Pauta","table.cell_column":"Total Reseñas"}	1	2	\N	native	f	\N	\N	\N	f	\N	\N	[{"database_type":"text","semantic_type":null,"lib/